def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            cells = set()
            q = [(r, c)]
            seen.add((r, c))
            while q:
                y, x = q.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                        (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)

            # A component is closed if its bounding box contains an
            # empty region not connected to the bounding-box boundary.
            empty = {(y, x) for y in range(minr, maxr + 1)
                     for x in range(minc, maxc + 1) if (y, x) not in cells}
            outside = set()
            q = deque()
            for y, x in empty:
                if y in (minr, maxr) or x in (minc, maxc):
                    outside.add((y, x))
                    q.append((y, x))
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if p in empty and p not in outside:
                        outside.add(p)
                        q.append(p)
            closed = len(outside) < len(empty)

            objects.append({
                "cells": cells,
                "closed": closed,
                "minr": minr,
                "maxr": maxr,
            })

    out = [[0] * w for _ in range(h)]

    for closed, upward in ((True, True), (False, False)):
        group = [o for o in objects if o["closed"] == closed]
        group.sort(key=lambda o: o["minr"] if upward else -o["maxr"])
        settled = set()

        for obj in group:
            cells = obj["cells"]
            shift = 0
            while True:
                step = -1 if upward else 1
                moved = {(y + shift + step, x) for y, x in cells}
                if any(y < 0 or y >= h for y, x in moved):
                    break
                if moved & settled:
                    break
                shift += step

            for y, x in cells:
                settled.add((y + shift, x))

    # Write the settled components using the same gravity order.
    for closed, upward in ((True, True), (False, False)):
        group = [o for o in objects if o["closed"] == closed]
        group.sort(key=lambda o: o["minr"] if upward else -o["maxr"])
