                step = -1 if upward else 1
                moved = {(y + shift + step, x) for y, x in cells}
                if any(y < 0 or y >= h for y, x in moved) or moved & settled:
                    break
                shift += step
            color = grid[next(iter(cells))[0]][next(iter(cells))[1]]
            for y, x in cells:
                out[y + shift][x] = color
                settled.add((y + shift, x))

    return out
